begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select extensions.no_plan();
insert into auth.users(id,email) values('11111111-1111-4111-8111-111111111111','sync-a@example.invalid'),('22222222-2222-4222-8222-222222222222','sync-b@example.invalid');
select extensions.ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='pickleup_private.sync_operation_epochs'::regclass),'epoch ledger FORCE RLS');
select extensions.ok(not has_table_privilege('authenticated','pickleup_private.sync_operation_epochs','SELECT,INSERT,UPDATE,DELETE'),'client epoch ledger denied');
select extensions.ok(not has_table_privilege('pickleup_api','pickleup_private.sync_operation_epochs','UPDATE,DELETE'),'epoch binding append-only');
select extensions.ok(not has_function_privilege('anon','public.prepare_sync(integer)','EXECUTE'),'anon handshake denied');
select extensions.ok(not has_function_privilege('anon','public.apply_sync_operation(uuid,text,text,text,text,uuid,jsonb,integer)','EXECUTE'),'anon fenced write denied');
select extensions.ok((select prosecdef and proowner='pickleup_api'::regrole and proconfig @> array['search_path=""'] from pg_proc where oid='public.apply_sync_operation(uuid,text,text,text,text,uuid,jsonb,integer)'::regprocedure),'fenced writer narrow owner/search_path');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select extensions.is(public.prepare_sync(2)->>'status','upgrade_required','handshake protocol checked');
select set_config('test.sync_epoch',(public.prepare_sync()->>'epoch'),true);
select extensions.is(public.prepare_sync()->>'server_revision','0','prepare does not create business change');
select extensions.is(public.prepare_sync()->>'epoch',current_setting('test.sync_epoch'),'prepare stable epoch');
select extensions.is(public.apply_sync_operation('44444444-4444-4444-8444-444444444444','user_preferences','self','put','0','33333333-3333-4333-8333-333333333333','{"target_days":4}')->>'status','reset_required','wrong epoch rejected before mutation');
select extensions.is(public.apply_sync_operation('44444444-4444-4444-8444-444444444444','user_preferences','self','put','0',current_setting('test.sync_epoch')::uuid,'{"target_days":4}')->>'status','applied','fenced CAS applied');
select extensions.is(public.apply_sync_operation('44444444-4444-4444-8444-444444444444','user_preferences','self','put','0',current_setting('test.sync_epoch')::uuid,'{"target_days":4}')->>'replayed','true','same epoch exact replay');
select extensions.is(public.apply_sync_operation('44444444-4444-4444-8444-444444444444','user_preferences','self','put','0',current_setting('test.sync_epoch')::uuid,'{"target_days":5}')->>'code','operation_id_reused','frozen request cannot change');
select extensions.is(public.apply_sync_operation('55555555-5555-4555-8555-555555555555','profiles','self','put','0',current_setting('test.sync_epoch')::uuid,'{}')->>'status','invalid','sender domain allowlist');
select extensions.is(public.apply_sync_operation('55555555-5555-4555-8555-555555555555','user_preferences','self','put','0',current_setting('test.sync_epoch')::uuid,'{"target_days":2}')->>'status','conflict','domain conflict HTTP envelope');
select extensions.is(public.apply_sync_operation('66666666-6666-4666-8666-666666666666','user_preferences','self','put','1',current_setting('test.sync_epoch')::uuid,'{"user_id":"22222222-2222-4222-8222-222222222222"}')->>'status','invalid','owner injection denied');
reset role;
update pickleup_private.sync_heads set epoch='77777777-7777-4777-8777-777777777777' where user_id='11111111-1111-4111-8111-111111111111';
set local role authenticated;
select extensions.is(public.apply_sync_operation('44444444-4444-4444-8444-444444444444','user_preferences','self','put','0',current_setting('test.sync_epoch')::uuid,'{"target_days":4}')->>'status','reset_required','restore fences old receipt replay');
select extensions.is(public.apply_sync_operation('44444444-4444-4444-8444-444444444444','user_preferences','self','put','0','77777777-7777-4777-8777-777777777777','{"target_days":4}')->>'code','operation_epoch_mismatch','operation cannot rebind to restored epoch');
select extensions.is((select revision::text from public.user_preferences),'1','fence rejection leaves business revision unchanged');
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select extensions.is((select count(*)::text from public.user_preferences),'0','B sees no A data');
select extensions.is(public.apply_sync_operation('44444444-4444-4444-8444-444444444444','user_preferences','self','put','0','77777777-7777-4777-8777-777777777777','{"target_days":4}')->>'status','reset_required','B cannot use A epoch');
select extensions.is(public.apply_sync_operation('44444444-4444-4444-8444-444444444444','user_preferences','self','put','0',(public.prepare_sync()->>'epoch')::uuid,'{"target_days":2}')->>'status','applied','same operation UUID independent under B');
reset role;
select * from extensions.finish();
rollback;
